package steps

import (
	"fmt"
	"strconv"
)

func phrase7c963587b98a9c9fa59fafbd25518c3af0d8d428753a4c888f114e5a06aa3242(state *State, args []string) error {
	const phrase = "the number is {value:number}"
	const zeroWord = "no"

	if len(args) != 1 {
		return fmt.Errorf("%s: expected 1 argument, got %d", phrase, len(args))
	}

	raw := args[0]
	value := 0
	if raw != zeroWord {
		parsed, err := strconv.Atoi(raw)
		if err != nil {
			return fmt.Errorf("%s: %q is not an integer: %w", phrase, raw, err)
		}
		value = parsed
	}

	state.Value = value
	state.HasValue = true
	return nil
}

package steps

import (
	"fmt"
	"strconv"
)

func phraseed02cd0805872c6dc539a79f13857bcae5921c4b2ff964f4091e2a4a4e97246a(state *State, args []string) error {
	const phrase = "the result is {value:number}"
	// The engine's pattern for a number term also accepts the word form of
	// zero, so accept it here exactly as the Given for the same term does.
	const zeroWord = "no"

	if len(args) != 1 {
		return fmt.Errorf("%s: expected 1 argument, got %d", phrase, len(args))
	}

	raw := args[0]
	expected := 0
	if raw != zeroWord {
		parsed, err := strconv.Atoi(raw)
		if err != nil {
			return fmt.Errorf("%s: %q is not an integer: %w", phrase, raw, err)
		}
		expected = parsed
	}

	if !state.HasResult {
		return fmt.Errorf("%s: no result observed; a When must run the double command first", phrase)
	}

	if state.Result != expected {
		return fmt.Errorf("%s: double printed %d on stdout, want %d", phrase, state.Result, expected)
	}

	return nil
}

package steps

import (
	"bytes"
	"context"
	"fmt"
	"os/exec"
	"strconv"
	"strings"
	"time"
)

func phrasefd1683cb9efb040dcb9ff323bbe5d2d3e9f958d39b3e3e7eafcb136f94b8a9df(state *State, args []string) error {
	const phrase = "the number is doubled"
	// The suite's package directory is tests/calc, so the host root the
	// declared CLI document runs `double` from is two levels up.
	const hostRoot = "../.."
	const command = "double"
	const runTimeout = 2 * time.Minute

	if len(args) != 0 {
		return fmt.Errorf("%s: expected 0 arguments, got %d", phrase, len(args))
	}
	if !state.HasValue {
		return fmt.Errorf("%s: no number supplied; a Given must set the number first", phrase)
	}

	ctx, cancel := context.WithTimeout(context.Background(), runTimeout)
	defer cancel()

	value := strconv.Itoa(state.Value)
	cmd := exec.CommandContext(ctx, "go", "run", "./services/calc", command, value)
	cmd.Dir = hostRoot

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		return fmt.Errorf(
			"%s: running %s %s from %s failed: %w: %s",
			phrase, command, value, hostRoot, err, strings.TrimSpace(stderr.String()),
		)
	}

	raw := strings.TrimSpace(stdout.String())
	result, err := strconv.Atoi(raw)
	if err != nil {
		return fmt.Errorf("%s: stdout %q is not an integer: %w", phrase, raw, err)
	}

	state.Result = result
	state.HasResult = true
	return nil
}

package steps

func Register(suite interface {
	Step(string, func(*State, []string) error)
}) {
	suite.Step("\\Athe number is ((?:[0-9]+|no))\\z", phrase7c963587b98a9c9fa59fafbd25518c3af0d8d428753a4c888f114e5a06aa3242)

	suite.Step("\\Athe number is doubled\\z", phrasefd1683cb9efb040dcb9ff323bbe5d2d3e9f958d39b3e3e7eafcb136f94b8a9df)

	suite.Step("\\Athe result is ((?:[0-9]+|no))\\z", phraseed02cd0805872c6dc539a79f13857bcae5921c4b2ff964f4091e2a4a4e97246a)
}

package steps

// State carries what one calc scenario hands from step to step.
//
// Value is the integer argument the next `double` command runs with;
// HasValue records that a Given actually supplied it, so a When can
// refuse to run the command on an unset slot instead of silently
// defaulting to 0.
//
// Result is the integer the `double` command printed on stdout, and
// HasResult records that the command actually ran, so a Then observes
// a real run instead of comparing against a zero value.
type State struct {
	Value     int
	HasValue  bool
	Result    int
	HasResult bool
}
